from collections import Counter

def word_frequencies(k, paragraph):
    # Normalize the paragraph: convert to lowercase and remove punctuation
    normalized_paragraph = re.sub(r'[^\w\s]', ' ', paragraph).lower()

    # Split the paragraph into words
    words = normalized_paragraph.split()

    # Count the frequency of each word
    word_count = Counter(words)

    # Sort the words first by frequency (in descending order), then alphabetically
    sorted_words = sorted(word_count.items(), key=lambda item: (-item[1], item[0].lower()))

    # Return top k frequent words
    return sorted_words[:k]"
